function Button({ children, icon: Icon, quiet, danger, className = '', ...props }) { return <button className={`button ${quiet ? 'quiet' : ''} ${danger ? 'danger' : ''} ${className}`} {...props}>{Icon && <Icon size={17} />}{children}</button>; }
function Field({ label: title, children, hint }) { return <label className="field"><span>{title}</span>{children}{hint && <small>{hint}</small>}</label>; }
function Tag({ children, good, warning }) { return <span className={`tag ${good ? 'good' : ''} ${warning ? 'warning' : ''}`}>{children}</span>; }
function Empty({ icon: Icon = Film, title, children, action }) { return <div className="empty"><Icon size={32} /><h3>{title}</h3><p>{children}</p>{action}</div>; }
function Modal({ title, children, onClose }) {
  const dialog = useRef(null), close = useRef(onClose); close.current = onClose;
  useEffect(() => {
    const previous = document.activeElement, focusable = () => [...dialog.current.querySelectorAll('button,a[href],input,select,textarea,[tabindex="0"]')].filter(node => !node.disabled && node.getClientRects().length);
    focusable()[0]?.focus();
    const key = event => { if (event.key === 'Escape') close.current(); if (event.key === 'Tab') { const items = focusable(), first = items[0], last = items.at(-1); if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last?.focus(); } else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first?.focus(); } } };
    document.addEventListener('keydown', key); return () => { document.removeEventListener('keydown', key); previous?.focus?.(); };
  }, []);
  return <div className="modal-backdrop" onMouseDown={event => event.target === event.currentTarget && onClose()}><motion.section ref={dialog} role="dialog" aria-modal="true" aria-label={title} className="modal" initial={{ opacity: 0, y: 18 }} animate={{ opacity: 1, y: 0 }} transition={{ type: 'spring', damping: 25, stiffness: 280 }}><div className="modal-title"><h2>{title}</h2><Button quiet icon={X} aria-label="Close dialog" onClick={onClose} /></div>{children}</motion.section></div>;
}
