  useEffect(() => { if (!session?.authenticated) return; const timer = setInterval(() => { refreshMedia().catch(() => {}); if (screen === 'settings') api('/settings').then(setSettings).catch(() => {}); }, 4000); return () => clearInterval(timer); }, [screen, session?.authenticated]);
  async function act(work, message) { setError(''); setBusy(true); try { const result = await work(); await load(); await refreshMedia(); if (message) { setNotice(message); setTimeout(() => setNotice(''), 4000); } return result; } catch (error) { setError(error.message); } finally { setBusy(false); } }
